// The city's texts (city.js) in Italian, as the sentences take them: server after "Il server …" ("Il server del Comune
// di Brno non risponde"), dataName as the subject ("La carta tecnica di Brno al momento non risponde"), dataShort after
// "dati" with its preposition ("secondo i dati del Comune di Brno e di OSM"), techMap after "Caricamento …"
// ("Caricamento della carta tecnica di Brno…"), parkingSource and credit as labels.
const own = (name, of, map, data, parking, credit) => ({
  server: of, dataName: `La ${map}`, dataShort: `${data} e di OSM`, techMap: `della ${map}`,
  parkingSource: parking, rulesHead: `Larghezze secondo il Manuale dell'IPR di Praga (C.2), indicative per ${name}:`, credit,
});
// own() for an inventory (masculine: "il catasto stradale").
const ownM = (name, of, map, data, parking, credit) => ({ ...own(name, of, map, data, parking, credit), dataName: `Il ${map}`, techMap: `del ${map}` });
const NATIONAL = "La carta tecnica del ČÚZK";
const TECH_PARKING = "parcheggi dalla carta tecnica";
const RUIAN = "RÚIAN © ČÚZK, 2026 (CC BY 4.0, modificato)";
